/**
 * Sidebar info for a logical file.
 */
public struct FileInfo {
    public var name: String
    /**
     * "strings" or "xcstrings".
     */
    public var format: String
    public var locales: [String]
    public var sourceLanguage: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String, 
        /**
         * "strings" or "xcstrings".
         */format: String, locales: [String], sourceLanguage: String) {
        self.name = name
        self.format = format
        self.locales = locales
        self.sourceLanguage = sourceLanguage
    }
}

#if compiler(>=6)
extension FileInfo: Sendable {}
#endif


extension FileInfo: Equatable, Hashable {
    public static func ==(lhs: FileInfo, rhs: FileInfo) -> Bool {
        if lhs.name != rhs.name {
            return false
        }
        if lhs.format != rhs.format {
            return false
        }
        if lhs.locales != rhs.locales {
            return false
        }
        if lhs.sourceLanguage != rhs.sourceLanguage {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(name)
        hasher.combine(format)
        hasher.combine(locales)
        hasher.combine(sourceLanguage)
    }
