/**
 * One row in the central key table.
 */
public struct KeyRow {
    public var key: String
    /**
     * Locale code → optional value (None = key absent for that locale).
     */
    public var translations: [String: String?]
    /**
     * Locales where this key is missing.
     */
    public var missingLocales: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(key: String, 
        /**
         * Locale code → optional value (None = key absent for that locale).
         */translations: [String: String?], 
        /**
         * Locales where this key is missing.
         */missingLocales: [String]) {
        self.key = key
        self.translations = translations
        self.missingLocales = missingLocales
    }
}

#if compiler(>=6)
extension KeyRow: Sendable {}
#endif


extension KeyRow: Equatable, Hashable {
    public static func ==(lhs: KeyRow, rhs: KeyRow) -> Bool {
        if lhs.key != rhs.key {
            return false
        }
        if lhs.translations != rhs.translations {
            return false
        }
        if lhs.missingLocales != rhs.missingLocales {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(key)
        hasher.combine(translations)
        hasher.combine(missingLocales)
    }
}



