/**
 * Errors surfaced to Swift.
 */
public enum LocusError: Swift.Error {

    
    
    /**
     * The path does not exist or is not accessible.
     */
    case NotFound(path: String
    )
    /**
     * A file was not found within the project.
     */
    case FileNotFound(name: String
    )
    /**
     * A key already exists when trying to add it.
     */
    case KeyAlreadyExists(key: String
    )
    /**
     * A key was not found when trying to delete it.
     */
    case KeyNotFound(key: String
    )
    /**
     * An IO error occurred during scanning or saving.
     */
    case Io(message: String
    )
    /**
     * A parse error in a `.xcstrings` file.
     */
    case Parse(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLocusError: FfiConverterRustBuffer {
    typealias SwiftType = LocusError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LocusError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            path: try FfiConverterString.read(from: &buf)
            )
        case 2: return .FileNotFound(
            name: try FfiConverterString.read(from: &buf)
            )
        case 3: return .KeyAlreadyExists(
            key: try FfiConverterString.read(from: &buf)
            )
        case 4: return .KeyNotFound(
            key: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Parse(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LocusError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .FileNotFound(name):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .KeyAlreadyExists(key):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .KeyNotFound(key):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Parse(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


