private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_locus_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_locus_core_checksum_func_load_project() != 14939) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_add_key() != 49019) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_delete_key() != 14682) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_files() != 34101) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_find_missing() != 14132) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_keys() != 50705) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_root_path() != 41671) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_save() != 29154) {
