        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_search_by_text() != 9486) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_locus_core_checksum_method_locusproject_set_value() != 57384) {
